Given a stack s, remove the middle element of it without using any additional data structure.Input: s = [10, 20, 30, 40, 50]Output: s = [10, 20, 40, 50]Explanation: After deleting the mid which is 30, stack will look like [10, 20, 40, 50].Input: s = [1, 2, 3, 4]Output:  s = [1, 3, 4]Explanation: The stack has 10 elements (even), there are two mid elements 2 and 3, we delete the first of the two.Try It YourselfNote :  The output printed by the following codes is reverse of the order as we pop the top elements one by one and print.Table of ContentUsing Vector - O(n) Time and O(n) SpaceUsing Recursion - O(n) Time and O(n) SpaceUsing Temporary Stack - O(n) Time and O(n) SpaceUsing Vector - O(n) Time and O(n) SpaceCreate a vector to store stack elements.Pop all elements from the stack and store them in the vector.Identify the middle element index: n/2 for even n, ceil(n/2) for odd n (0-based indexing).Skip the middle element and push the remaining elements back to the stack in reverse order.
            C++

    //Driver Code Starts
#include <iostream>
#include <stack>
#include <vector>
using namespace std;
//Driver Code Ends


void deleteMiddle(stack<int>& st) {
    vector<int> elements;

    // Transfer stack elements to a vector
    while (!st.empty()) {
        elements.push_back(st.top());
        st.pop();
    }

    // Compute middle index
    int midIndex = elements.size() / 2;

    // Erase the middle element
    elements.erase(elements.begin() + midIndex);

    // Push elements back to the stack in reverse order
    for (int i = elements.size() - 1; i >= 0; --i) {
        st.push(elements[i]);
    }
}

//Driver Code Starts

int main() {
    stack<int> st;
    st.push(10);
    st.push(20);
    st.push(30);
    st.push(40);
    st.push(50);

    deleteMiddle(st);

    // Print the remaining stack
    while (!st.empty()) {
        cout << st.top() << " ";
        st.pop();
    }

    return 0;
}

