void deleteMid(stack<int>& st)
{
    int n = st.size();
    stack<int> tempSt;
    int count = 0;

    // Move the top half of the elements to a temporary stack
    while (count < n / 2) {
        tempSt.push(st.top());
        st.pop();
        count++;
    }

    // Remove the middle element
    st.pop();

    // Restore the remaining elements back to the original stack
    while (!tempSt.empty()) {
        st.push(tempSt.top());
        tempSt.pop();
    }
}

